      --muted: var(--editorial-muted);
      --line: var(--editorial-line);
      --light-line: var(--editorial-line);
      --tint: var(--editorial-surface);
      --rust: var(--editorial-clay);
      --serif: var(--font-display);
      --sans: var(--font-body);
      padding-top: 0;
    }
    .rebuild-guide :is(.wrap, .rebuild-approval, .rebuild-footlinks) {
      width: 100%;
      max-width: var(--editorial-content);
    }
